# One action, one physical ODBC process lifetime. No password input/output.
$ErrorActionPreference='Stop';$root='C:\Users\Xaser\Desktop\ERP';$source=Join-Path $root 'kaynak';$dir=Join-Path $root 'kurulum\first-sale-activation-v3';$connection=$null;$mode='INPUT';$stage='INPUT'
function Compile-Child([string]$fn,$identity=$null){$allowed=@('compileFirstSaleAdminObservation','compileFirstSaleDisabledVerification','compileFirstSaleActivation','compileFirstSaleDisableCompensation','compileFirstSaleActiveState','compileFirstSaleInactiveState');if($fn -cnotin $allowed){throw 'COMPILER_REJECTED'};$arg=if($identity){$identity|ConvertTo-Json -Compress}else{''};$js="import {$fn} from './scripts/desktop-empty/first-sale-activation-plan.mjs';process.stdout.write(JSON.stringify($fn($arg)));";return (Invoke-FirstSaleNode @('--input-type=module','-e',$js) $null|ConvertFrom-Json -AsHashtable)}
try{
 if(-not [Console]::IsInputRedirected -or [Security.Principal.WindowsIdentity]::GetCurrent().Name -cne 'SEMIH\Xaser'){throw 'PRIVATE_PARENT_REQUIRED'}
 [Console]::InputEncoding=[Text.UTF8Encoding]::new($false,$true);$text=[Console]::In.ReadToEnd();if($text.Length -gt 8192){throw 'INPUT_LIMIT'};$v=$text|ConvertFrom-Json -AsHashtable
 if($v.Count -ne 7 -or @($v.Keys|Where-Object{$_ -cnotin @('protocol','mode','attemptId','supervisorPid','packageHash','identity','previousConnections')}).Count -or $v.protocol -ne 2 -or $v.mode -cnotin @('verify','activate','disable','active','inactive') -or $v.attemptId -cnotmatch '^[a-f0-9-]{36}$' -or $v.packageHash -cnotmatch '^[A-F0-9]{64}$' -or $v.identity.Count -ne 2 -or $v.identity.loginSid -cnotmatch '^0x[0-9A-F]{32}$' -or $v.identity.operatorId -cnotmatch '^[1-9][0-9]{0,15}$' -or @($v.previousConnections).Count -gt 10 -or @($v.previousConnections|Where-Object{$_ -cnotmatch '^[a-fA-F0-9-]{36}$'}).Count){throw 'INPUT_REJECTED'};$mode=$v.mode
 $claim=Get-Content -Raw -LiteralPath (Join-Path $dir 'attempt.json')|ConvertFrom-Json -AsHashtable -DateKind String
 $me=Get-CimInstance Win32_Process -Filter "ProcessId=$PID";$parent=Get-CimInstance Win32_Process -Filter "ProcessId=$($me.ParentProcessId)"
 if($claim.protocol -ne 2 -or $claim.attemptId -cne $v.attemptId -or $claim.supervisorPid -ne $v.supervisorPid -or $me.ParentProcessId -ne $v.supervisorPid -or $claim.packageHash -cne $v.packageHash -or $claim.identity.loginSid -cne $v.identity.loginSid -or $claim.identity.operatorId -cne $v.identity.operatorId -or $parent.CommandLine -cnotlike '* -File C:\Users\Xaser\Desktop\ERP\kaynak\scripts\desktop-empty\activate-first-sale.ps1 -ExecuteReviewedActivation' -or [Math]::Abs(($parent.CreationDate.ToUniversalTime()-[DateTime]::Parse($claim.supervisorStartedUtc).ToUniversalTime()).TotalMilliseconds) -gt 10){throw 'PARENT_CLAIM_REJECTED'}
 $packageFile=Join-Path $root 'kurulum\first-sale-package.json';if((Get-FileHash -LiteralPath $packageFile -Algorithm SHA256).Hash -cne $v.packageHash){throw 'PACKAGE_REJECTED'};$pkg=Get-Content -Raw -LiteralPath $packageFile|ConvertFrom-Json -AsHashtable
 foreach($group in @($pkg.sources,$pkg.helpers)){foreach($name in $group.Keys){if((Get-FileHash -LiteralPath (Join-Path $source $name) -Algorithm SHA256).Hash.ToLowerInvariant() -cne $group[$name]){throw 'SOURCE_PIN_REJECTED'}}}
 foreach($lockName in @('desktop-empty-schema.owner.lock','desktop-initial-reader.owner.lock')){$probe=$null;$blocked=$false;try{$probe=[IO.File]::Open((Join-Path $root $lockName),[IO.FileMode]::Open,[IO.FileAccess]::ReadWrite,[IO.FileShare]::None)}catch [IO.IOException]{$blocked=$true}finally{if($probe){$probe.Dispose()}};if(-not $blocked){throw 'PARENT_OWNER_LOCK_NOT_HELD'}}
 if(Test-Path -LiteralPath (Join-Path $dir ($mode+'.dispatch.json'))){throw 'MODE_ALREADY_DISPATCHED_NO_RETRY'}
 . (Join-Path $source 'scripts\desktop-empty\first-sale-runner-common.ps1')
 $connection=Open-FirstSaleAdmin;$stage='HEADER';$headerPlan=Compile-Child 'compileFirstSaleAdminObservation';$header=Read-FirstSaleScalar $connection $headerPlan.sql|ConvertFrom-Json -AsHashtable
 if($header.connectionId -cnotmatch '^[a-fA-F0-9-]{36}$' -or $header.sessionId -lt 1){throw 'HEADER_REJECTED'}
 foreach($old in @($v.previousConnections)){$clear=$false;for($i=0;$i -lt 10;$i++){if([int](Read-FirstSaleScalar $connection "SELECT COUNT(*) FROM sys.dm_exec_connections WHERE connection_id=CONVERT(uniqueidentifier,'$old');") -eq 0){$clear=$true;break};Start-Sleep -Milliseconds 50};if(-not $clear -or $old -ceq $header.connectionId){throw 'PREVIOUS_CONNECTION_NOT_CLOSED'}}
 $fn=@{verify='compileFirstSaleDisabledVerification';activate='compileFirstSaleActivation';disable='compileFirstSaleDisableCompensation';active='compileFirstSaleActiveState';inactive='compileFirstSaleInactiveState'}[$mode];$plan=Compile-Child $fn $(if($mode -ceq 'verify'){$null}else{$v.identity})
 Write-FirstSaleNew (Join-Path $dir ($mode+'.dispatch.json')) @{state='UNKNOWN';mode=$mode;attemptId=$v.attemptId;childPid=$PID;connectionId=$header.connectionId;sessionId=$header.sessionId;sqlHash=$plan.sqlSha256;time=[DateTime]::UtcNow.ToString('o')}
 $stage='SQL';$result=Read-FirstSaleScalar $connection $plan.sql
 if($mode -ceq 'verify'){$identity=[string]$result|ConvertFrom-Json -AsHashtable;if($identity.loginSid -cne $v.identity.loginSid -or $identity.operatorId -cne $v.identity.operatorId){throw 'VERIFIED_IDENTITY_CHANGED'}}
 elseif($mode -ceq 'activate'){if($result -cne 'FIRST_SALE_ACTIVATED'){throw 'ACTIVATION_RESULT_REJECTED'}}
 elseif($mode -ceq 'disable'){if($result -cne 'FIRST_SALE_DISABLED'){throw 'DISABLE_RESULT_REJECTED'}}
 elseif([int]$result -ne 1){throw 'INDEPENDENT_STATE_REJECTED'}
 Write-FirstSaleNew (Join-Path $dir ($mode+'.result.json')) @{state='COMMAND_ACKNOWLEDGED';mode=$mode;attemptId=$v.attemptId;childPid=$PID;connectionId=$header.connectionId;identity=$v.identity;sqlHash=$plan.sqlSha256;time=[DateTime]::UtcNow.ToString('o')};[Console]::WriteLine('FIRST_SALE_CHILD_VERIFIED')
}catch{$numbers=@();$safe=@();$cursor=$_.Exception;while($cursor){if($cursor -is [System.Data.Odbc.OdbcException]){$numbers=@($cursor.Errors|ForEach-Object{$_.NativeError});foreach($e in $cursor.Errors){$safe+=@([regex]::Matches($e.Message,'FIRST_SALE_ACTIVATION_FAILURE stage=[0-9]+ error=[0-9]+ cleanup=[0-9]+ label=[A-Z_]+')|ForEach-Object{$_.Value})};break};$cursor=$cursor.InnerException};$code=if($_.Exception.Message -cmatch '^[A-Z_]{3,100}$'){$_.Exception.Message}else{'UNCLASSIFIED'};[Console]::Error.WriteLine("ACTIVATION_CHILD_STOPPED mode=$mode stage=$stage code=$code native=$($numbers -join ',') details=$($safe -join ',')");exit 1}
finally{if($connection){$connection.Dispose()}}
